public class SquareTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Square three = new Square(3.0);
        check("area of side 3", 9.0, three.area());
        check("area of side 2.5", 6.25, new Square(2.5).area());
        check("area of side 0", 0.0, new Square(0.0).area());

        Shape shape = new Square(4.0);
        check("area through a Shape reference", 16.0, shape.area());
        check("describe() uses the overridden area()", "Shape with area 16.0", shape.describe());
        check("describe() called directly on a Square", "Shape with area 9.0", three.describe());
        check("a Square is a Shape", true, three instanceof Shape);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

