abstract class Shape {

    public abstract double area();

    public String describe() {
        return "Shape with area " + area();
    }
}

public class Square extends Shape {

    private double side;

    public Square(double side) {
        this.side = side;
    }

    @Override
    public double area() {
        return side * side;
    }
}
